tape( 'the function supports specifying a stride', function test( t ) {
	var expected;
	var x;

	x = [
		2.0,  // 0
		-3.0,
		-5.0, // 1
		7.0,
		6.0   // 2
	];
	expected = [
		1.0,  // 0
		-3.0,
		0.0,  // 1
		7.0,
		-1.0  // 2
	];

	cosineWave( 3, 4, 1.0, 0, x, 2 );
	t.deepEqual( x, expected, 'returns expected value' );
	t.end();
});

