tape( 'the function supports view offsets', function test( t ) {
	var expected;
	var x0;
	var x1;

	x0 = new Float64Array([
		1.0,
		2.0, // 0
		3.0,
		4.0, // 1
		5.0,
		6.0  // 2
	]);
	expected = new Float64Array([
		1.0,
		1.0, // 0
		3.0,
		0.0, // 1
		5.0,
		-1.0 // 2
	]);

	x1 = new Float64Array( x0.buffer, x0.BYTES_PER_ELEMENT*1 );

	cosineWave( 3, 4, 1.0, 0, x1, 2 );
	t.deepEqual( x0, expected, 'returns expected value' );
	t.end();
});

tape( 'if `stride` is equal to `1`, the function efficiently generates a cosine wave in a strided array', function test( t ) {
	var phaseOffset;
	var amplitude;
	var expected;
	var period;
	var theta;
	var s;
	var x;
	var i;

	phaseOffset = 0;
	amplitude = 1.0;
	period = 4;
	s = 2.0 / period;
	theta = -phaseOffset;
	x = new Float64Array( 100 );
	expected = new Float64Array( x.length );
	for ( i = 0; i < x.length; i++ ) {
		x[ i ] = i;
		expected[ i ] = amplitude * cospi( s * theta );
		theta += 1.0;
	}
	cosineWave( x.length, 4, 1.0, 0, x, 1 );
	t.deepEqual( x, expected, 'returns expected value' );

	theta = -phaseOffset;
	x = new Float64Array( 240 );
	expected = new Float64Array( x.length );
	for ( i = 0; i < x.length; i++ ) {
		x[ i ] = i;
		expected[ i ] = amplitude * cospi( s * theta );
		theta += 1.0;
	}
	cosineWave( x.length, 4, 1.0, 0, x, 1 );
	t.deepEqual( x, expected, 'returns expected value' );

	t.end();
});
